PRAGMA foreign_keys=ON;
CREATE TABLE Users(Id INTEGER PRIMARY KEY,Username TEXT NOT NULL UNIQUE,PasswordHash TEXT NOT NULL,Role TEXT NOT NULL,CreatedAt TEXT NOT NULL);
CREATE TABLE Visitors(Id INTEGER PRIMARY KEY,FullName TEXT NOT NULL,Email TEXT NOT NULL UNIQUE,Phone TEXT NOT NULL,Company TEXT NOT NULL,CreatedAt TEXT NOT NULL);
CREATE TABLE Visits(Id INTEGER PRIMARY KEY,Reference TEXT NOT NULL UNIQUE,VisitorId INTEGER NOT NULL REFERENCES Visitors(Id),HostName TEXT NOT NULL,Purpose TEXT NOT NULL,ScheduledAt TEXT NOT NULL,Status TEXT NOT NULL,BadgeNumber TEXT UNIQUE,CheckedInAt TEXT,CheckedOutAt TEXT,CreatedById INTEGER NOT NULL REFERENCES Users(Id),CreatedAt TEXT NOT NULL);
